# add_priors ----
## Setup ----
# `small_parameters` is in helper-small-parameters.R.
parameters_with_prior <- small_parameters |>
  add_priors(
    log_q ~ normal(mean = log(0.5), sd = 0.2),
    module_name = "Fleet",
    fleet = "survey1"
  )
# Recruitment with a log_devs process, a growth module, and a survey log_q
# with an AR1 process, with priors on 4 kinds of parameter.
recruitment <- tibble::tibble(
  module_name = "Recruitment",
  module_type = "BevertonHolt",
  label = c("log_rzero", "logit_steep", "log_devs", "log_sd"),
  value = c(10, 0.5, 0, log(0.4)),
  estimation_type = c(
    "fixed_effects", "fixed_effects", "random_effects", "fixed_effects"
  ),
  distribution_type = c(NA, NA, "process", "process"),
  distribution = c(NA, NA, "Dnorm", "Dnorm")
)
growth <- tibble::tibble(
  module_name = "Growth",
  module_type = "VonBertalanffySchnute",
  label = c("mean_length_young", "mean_length_old", "growth_coefficient"),
  value = c(280, 720, 0.2),
  estimation_type = "fixed_effects"
)
parameters_with_priors <- small_parameters |>
  dplyr::bind_rows(recruitment, growth) |>
  add_process(
    log_q ~ 1 + ar1(1 | year),
    module_name = "Fleet",
    fleet = "survey1",
    sd = list(value = 0.2, estimation_type = "fixed_effects"),
    rho = list(value = 0.5, estimation_type = "fixed_effects")
  ) |>
  add_priors(
    logit_steep ~ normal(mean = 0.5, sd = 0.3),
    module_name = "Recruitment"
  ) |>
  add_priors(
    log_sd ~ normal(mean = log(0.6), sd = 0.2),
    module_name = "Recruitment"
  ) |>
  add_priors(
    log_q_log_sd ~ normal(mean = log(0.2), sd = 0.5),
    module_name = "Fleet",
    fleet = "survey1"
  ) |>
  add_priors(
    log_mean_length_young ~ normal(mean = log(280), sd = 0.1),
    module_name = "Growth"
  )

## IO correctness ----
test_that("`add_priors()` works with correct inputs", {
  prior_rows <- dplyr::filter(parameters_with_prior, target_label %in% "log_q")
  #' @description Test that `add_priors()` writes 1 expected_mean row and 1 log_sd row.
  expect_equal(
    object = prior_rows[["label"]],
    expected = c("expected_mean", "log_sd")
  )
  #' @description Test that `add_priors()` writes the prior mean and the log of the prior sd.
  expect_equal(
    object = prior_rows[["value"]],
    expected = c(log(0.5), log(0.2))
  )
  #' @description Test that `add_priors()` writes the prior rows as constants.
  expect_true(all(prior_rows[["estimation_type"]] == "constant"))
  log_q_rows <- dplyr::filter(parameters_with_prior, label == "log_q")
  #' @description Test that `add_priors()` does not change the target's own rows.
  expect_true(is.na(log_q_rows[["distribution_type"]]))
  prior_mean <- log(0.5)
  #' @description Test that `add_priors()` finds variables in the prior, such as its mean, where the formula was written.
  expect_equal(
    object = small_parameters |>
      add_priors(
        log_q ~ normal(mean = prior_mean, sd = 0.2),
        module_name = "Fleet",
        fleet = "survey1"
      ) |>
      dplyr::filter(target_label %in% "log_q") |>
      dplyr::pull(value),
    expected = prior_rows[["value"]]
  )
})

test_that("`add_priors()` scores each shared value once", {
  parameters <- small_parameters |>
    add_process(
      log_Fmort ~ cut(year, c(-Inf, 3, Inf)),
      module_name = "Fleet",
      fleet = "fleet1"
    ) |>
    add_priors(
      log_Fmort ~ normal(mean = -1, sd = 0.5),
      module_name = "Fleet",
      fleet = "fleet1"
    )
  parameter_table <- FIMS:::initialize_parameters(
    parameters
  )[["parameter_table"]]
  prior <- FIMS:::prior_densities(parameter_table)[[1]]
  #' @description Test that a prior on 6 years in 2 time blocks, so 2 estimated values, gives 2 prior terms at the first year of each block.
  expect_equal(
    object = prior[["positions"]],
    expected = c(1L, 4L)
  )
})

test_that("`add_priors()` works on any parameter, named as the model names it", {
  densities <- FIMS:::initialize_densities(
    FIMS:::initialize_parameters(parameters_with_priors)[["parameter_table"]]
  )
  priors <- purrr::keep(
    densities,
    function(density) density[["distribution_type"]] == "prior"
  )
  #' @description Test that the target of each prior from `add_priors()` is the parameter's name in the model, on its estimation scale.
  expect_equal(
    object = purrr::map_chr(priors, "target"),
    expected = c(
      "Recruitment.logit_steep", "Recruitment.log_sd",
      "Fleet.survey1.log_q_log_sd", "Growth.log_mean_length_young"
    )
  )
  #' @description Test that the prior sd of a prior on the recruitment log_sd is named apart from the log_sd it is a prior on.
  expect_equal(
    object = priors[[2]][["hyperparameters"]][["log_sd"]],
    expected = "Recruitment.log_sd_prior_log_sd"
  )
  #' @description Test that `initialize_densities()` keeps the 2 processes after `add_priors()`, listed after the 4 priors.
  expect_equal(
    object = purrr::map_chr(densities, "distribution_type"),
    expected = c(rep("prior", 4), "process", "process")
  )
})

test_that("`add_priors()` adds the prior's negative log density to the objective", {
  data_4_model <- FIMSFrame(data_big)
  # The survey log_q and the recruitment log_sd are estimated, so each can
  # take a prior.
  parameters <- parameters_big |>
    dplyr::mutate(estimation_type = dplyr::if_else(
      (label == "log_q" & fleet %in% "survey1") |
        (module_name == "Recruitment" & label == "log_sd"),
      "fixed_effects", estimation_type
    ))
  get_jnll <- function(parameters) {
    fit <- parameters |>
      initialize_fims(data = data_4_model) |>
      fit_fims(optimize = FALSE)
    get_report(fit)[["jnll"]]
  }
  jnll_without_prior <- get_jnll(parameters)

  log_q_start <- dplyr::filter(
    parameters, label == "log_q", fleet %in% "survey1"
  )[["value"]]
  jnll_with_log_q_prior <- parameters |>
    add_priors(
      log_q ~ normal(mean = log(0.5), sd = 0.2),
      module_name = "Fleet",
      fleet = "survey1"
    ) |>
    get_jnll()
  #' @description Test that a normal prior on log_q adds its negative log density at the starting value to the joint negative log-likelihood.
  expect_equal(
    object = jnll_with_log_q_prior - jnll_without_prior,
    expected = -stats::dnorm(log_q_start, log(0.5), 0.2, log = TRUE)
  )

  log_sd_start <- dplyr::filter(
    parameters, module_name == "Recruitment", label == "log_sd"
  )[["value"]]
  jnll_with_log_sd_prior <- parameters |>
    add_priors(
      log_sd ~ normal(mean = log(0.6), sd = 0.2),
      module_name = "Recruitment"
    ) |>
    get_jnll()
  #' @description Test that a normal prior on the recruitment log_sd adds its negative log density at the starting value to the joint negative log-likelihood.
  expect_equal(
    object = jnll_with_log_sd_prior - jnll_without_prior,
    expected = -stats::dnorm(log_sd_start, log(0.6), 0.2, log = TRUE)
  )
})

## Edge handling ----
test_that("`add_priors()` accepts a prior mean for each value of the target", {
  # A hand-written prior on fleet1's log_Fmort (years 1 to 6) with 1 mean
  # per year, given with the target's timing so each mean stays with its year.
  per_year_prior <- small_parameters |>
    add_priors(
      log_Fmort ~ normal(mean = -1, sd = 0.5),
      module_name = "Fleet",
      fleet = "fleet1"
    ) |>
    dplyr::filter(!(target_label %in% "log_Fmort" & label == "expected_mean"))
  mean_rows <- dplyr::filter(small_parameters, label == "log_Fmort") |>
    dplyr::mutate(
      label = "expected_mean", value = -(1:6) / 10,
      estimation_type = "constant", target_label = "log_Fmort",
      distribution_type = "prior", distribution = "Dnorm"
    )
  table <- FIMS:::initialize_parameters(
    dplyr::bind_rows(per_year_prior, mean_rows)
  )[["parameter_table"]]
  prior <- FIMS:::prior_densities(table)[[1]]
  #' @description Test that a prior with 1 mean per year scores every year of its target.
  expect_equal(object = prior[["positions"]], expected = 1:6)

  #' @description Test that a prior with 1 mean per year but no timing errors, because the means could not be matched to their years.
  expect_error(
    object = FIMS:::prior_densities(FIMS:::initialize_parameters(
      dplyr::bind_rows(
        per_year_prior,
        dplyr::mutate(mean_rows, timing = NA_real_)
      )
    )[["parameter_table"]]),
    regexp = "do not match"
  )
})

## Error handling ----
test_that("`add_priors()` returns correct error messages", {
  #' @description Test that `add_priors()` errors for a target that already has a prior.
  expect_error(
    object = add_priors(
      parameters_with_prior,
      log_q ~ normal(mean = 0, sd = 1),
      module_name = "Fleet",
      fleet = "survey1"
    ),
    regexp = "already has a prior"
  )
  #' @description Test that `add_priors()` errors for a growth label without its estimation scale, so the scale is never guessed.
  expect_error(
    object = add_priors(
      parameters_with_priors,
      growth_coefficient ~ normal(mean = 0.2, sd = 0.1),
      module_name = "Growth"
    ),
    regexp = "log scale"
  )
  #' @description Test that `add_priors()` errors for a parameter with its own process.
  expect_error(
    object = add_priors(
      parameters_with_priors,
      log_devs ~ normal(mean = 0, sd = 1),
      module_name = "Recruitment"
    ),
    regexp = "has a process"
  )
  #' @description Test that `add_priors()` errors for a prior that is not `normal()`.
  expect_error(
    object = add_priors(
      small_parameters,
      log_q ~ uniform(min = -5, max = 0),
      module_name = "Fleet",
      fleet = "survey1"
    ),
    regexp = "priors\\s+are\\s+implemented"
  )
  #' @description Test that `add_priors()` errors for a target with no rows in the module.
  expect_error(
    object = add_priors(
      small_parameters,
      log_rzero ~ normal(mean = 10, sd = 1),
      module_name = "Recruitment"
    ),
    regexp = "There are no"
  )
  #' @description Test that `add_priors()` errors for a prior sd of 0, which has no log.
  expect_error(
    object = add_priors(
      small_parameters,
      log_q ~ normal(mean = log(0.5), sd = 0),
      module_name = "Fleet",
      fleet = "survey1"
    ),
    regexp = "must\\s+be\\s+1\\s+number\\s+>\\s+0"
  )
  #' @description Test that `add_priors()` errors for a prior with no sd.
  expect_error(
    object = add_priors(
      small_parameters,
      log_q ~ normal(mean = log(0.5)),
      module_name = "Fleet",
      fleet = "survey1"
    ),
    regexp = "must\\s+be\\s+1\\s+number\\s+>\\s+0"
  )
})
